import{_ as a,c as i,o as t,ag as r}from"./chunks/framework.DQvKz0xt.js";const c=JSON.parse('{"title":"动画模式概览 (Animate Mode Overview) - Rive 编辑器","description":"动画模式 (Animate Mode) Rive 拥有两种截然不同的模式：“设计模式 (Design)” 和 “动画模式 (Animate)”。当你处于动画模式时，编辑器界面会发生变化，显示创建动画所需的一切工具，包括时间轴、动画列表和插值面板。要快速切换模式，请使用 快捷键。","frontmatter":{"title":"动画模式概览 (Animate Mode Overview) - Rive 编辑器","description":"动画模式 (Animate Mode) Rive 拥有两种截然不同的模式：“设计模式 (Design)” 和 “动画模式 (Animate)”。当你处于动画模式时，编辑器界面会发生变化，显示创建动画所需的一切工具，包括时间轴、动画列表和插值面板。要快速切换模式，请使用 快捷键。","head":[["meta",{"name":"keywords","content":"Rive, Rive 中文文档, Rive 编辑器, 动画模式, 动画模式概览"}]]},"headers":[],"relativePath":"editor/animate-mode/overview.md","filePath":"editor/animate-mode/overview.md","lastUpdated":1774838907000}'),o={name:"editor/animate-mode/overview.md"};function n(d,e,m,l,s,p){return t(),i("div",null,[...e[0]||(e[0]=[r('<p>动画模式 (Animate Mode)</p><h1 id="动画模式概览-animate-mode-overview" tabindex="-1">动画模式概览 (Animate Mode Overview) <a class="header-anchor" href="#动画模式概览-animate-mode-overview" aria-label="Permalink to &quot;动画模式概览 (Animate Mode Overview)&quot;">​</a></h1><p>Rive 拥有两种截然不同的模式：“设计模式 (Design)” 和 “动画模式 (Animate)”。当你处于动画模式时，编辑器界面会发生变化，显示创建动画所需的一切工具，包括时间轴、动画列表和插值面板。要快速切换模式，请使用 <code>Tab</code> 快捷键。</p><p>在动画模式下，你会注意到 <a href="/docs/editor/interface-overview/inspector">检查器 (Inspector)</a> 中可以制作动画的属性旁边出现了“关键帧 (key)”图标。</p><h3 id="​-深入了解动画模式" tabindex="-1"><a href="#learn-more-about-animate-mode">​</a> 深入了解动画模式 <a class="header-anchor" href="#​-深入了解动画模式" aria-label="Permalink to &quot;[​](#learn-more-about-animate-mode) 深入了解动画模式&quot;">​</a></h3><h4 id="时间轴-timeline" tabindex="-1"><a href="/docs/editor/animate-mode/timeline">时间轴 (Timeline)</a> <a class="header-anchor" href="#时间轴-timeline" aria-label="Permalink to &quot;[时间轴 (Timeline)](/editor/animate-mode/timeline.md)&quot;">​</a></h4><p><a href="/docs/editor/animate-mode/timeline">Rive 界面显示了一个带有播放控制的时间轴，以及用于配置当前动画的选项。</a></p><h4 id="关键帧-keys" tabindex="-1"><a href="/docs/editor/animate-mode/keyframes">关键帧 (Keys)</a> <a class="header-anchor" href="#关键帧-keys" aria-label="Permalink to &quot;[关键帧 (Keys)](/editor/animate-mode/keyframes.md)&quot;">​</a></h4><p><a href="/docs/editor/animate-mode/keyframes">一旦为对象的属性设置了关键帧，它们就会出现在时间轴上。设置关键帧有几种不同的方式。</a></p><h4 id="插值与缓动-interpolation-easing" tabindex="-1"><a href="https://help.rive.app/editor/animate-mode/interpolation-easing" target="_blank" rel="noreferrer">插值与缓动 (Interpolation &amp; Easing)</a> <a class="header-anchor" href="#插值与缓动-interpolation-easing" aria-label="Permalink to &quot;[插值与缓动 (Interpolation &amp; Easing)](https://help.rive.app/editor/animate-mode/interpolation-easing)&quot;">​</a></h4><p><a href="https://help.rive.app/editor/animate-mode/interpolation-easing" target="_blank" rel="noreferrer">当你为一个属性设置两个关键帧时，两者之间的数值会自动计算，这被称为“插值”。</a></p><h4 id="绘制顺序动画-animating-draw-order" tabindex="-1"><a href="https://help.rive.app/editor/animate-mode/animating-draw-order" target="_blank" rel="noreferrer">绘制顺序动画 (Animating Draw Order)</a> <a class="header-anchor" href="#绘制顺序动画-animating-draw-order" aria-label="Permalink to &quot;[绘制顺序动画 (Animating Draw Order)](https://help.rive.app/editor/animate-mode/animating-draw-order)&quot;">​</a></h4><p><a href="https://help.rive.app/editor/animate-mode/animating-draw-order" target="_blank" rel="noreferrer">你可以在设计时通过调整层级面板来改变绘制顺序，并可以在动画模式中对其进行动画化处理。</a></p><p><a href="/docs/editor/constraints/scroll-constraint">滚动约束 (Scroll Constraints)</a><a href="/docs/editor/animate-mode/timeline">时间轴 (Timeline)</a></p>',14)])])}const v=a(o,[["render",n]]);export{c as __pageData,v as default};
